 const prefs=await store.preferences(principal),date=prefs.dates[0];for(const amount of ['11','13','17'])await expenseCreateC({...await expenseFieldsC(),amount});const overview=await store.cashOverview(principal);assert.equal(overview.status,200);const names={'operatingIncomeMtd':'Operating Income MTD','expensesMtd':'Expenses MTD','netProfitMtd':'Net Profit MTD','tommyWithdrawnMtd':'Tommy Withdrawn MTD','lisaWithdrawnMtd':'Lisa Withdrawn MTD','unsettledProfitMtd':'Unsettled Profit MTD','cashPoolRemaining':'Cash Pool Remaining','businessCashHeld':'Business Cash Held'},projection=Object.entries(names).map(([key,column])=>'"'+column+'"::text AS "'+key+'"').join(',');assert.deepEqual(overview.dashboard,(await admin.query('SELECT '+projection+' FROM "Cash Dashboard"')).rows[0]);const unknown=overview.accounts.find(a=>a.id===fixture.receivingAccountId);assert.equal(unknown.initialized,false);assert.equal(unknown.openingBalance,null);assert.equal(unknown.currentBalance,null);
