 assert.deepEqual(items.map(r=>({id:r.id,amount:r.amount,balance:r.balanceAfter,initialized:r.initialized,ledger:r.ledgerId,direction:r.direction})),expected);assert.equal(new Set(items.map(i=>i.id)).size,items.length);assert.ok(items.some(i=>i.amount.startsWith('-')));assert.ok(items.every(i=>i.balanceAfter===null&&i.initialized===false));
