test('F8-C06 First-day destination roundtrip uses complete eligible components and same receipt with alternate Lisa account',async()=>{for(const type of [loanTypesC[0],loanTypesC[1]]){const f=await firstdayTransitionC(type),account=randomUUID();await app.query('INSERT INTO "Cash Accounts"("Row ID","Ref Cash Holder","Account Label","Bank Name") VALUES($1,\'ch:lisa\',$2,\'Synthetic\')',[account,'C destination Lisa '+account]);const first=await correctionPlanCommandC(f.id,{...f.plan,cashAccountId:account}),original=await rows(f.original.requestId),r=await store.operation(principal,first);assert.equal(r.originalOutcome?.status,'applied',JSON.stringify(r));const item=(await store.paymentRecord(principal,f.id)).item;assert.equal(item.allocationMethod,'First-day Auto');assert.equal(item.cashAccountId,account);assert.equal(item.createdBy,OWNER_EMAIL);assert.equal(item.allocations.length,1);assert.equal(Number(item.allocations[0].interest),9);assert.equal((await admin.query('SELECT count(*)::int n FROM "Payments" WHERE "Ref Target Charge"=$1',[f.charge])).rows[0].n,1);const next=await correctionPlanCommandC(f.id,{...f.plan,cashAccountId:fixture.receivingAccountId,paymentMethod:'Cash',allocationMethod:'Selected Charges',targetChargeId:null}),back=await store.operation(principal,next);assert.equal(back.originalOutcome?.status,'applied',JSON.stringify(back));const before=await receiptEffectsC(f.id);await app.query('SELECT public.post_payment($1)',[f.id]);assert.deepEqual(await receiptEffectsC(f.id),before);assert.deepEqual(await rows(f.original.requestId),original);assert.deepEqual((await store.submit(principal,f.original)).originalOutcome,f.posted.originalOutcome);assert.deepEqual((await store.operation(principal,first)).originalOutcome,r.originalOutcome);assert.deepEqual((await store.operation(principal,next)).originalOutcome,back.originalOutcome)}});
test('F8-C07 invalid First-day destination date type auto borrower tender holder scope and partial components reject atomically',async()=>{const f=await firstdayTransitionC(),before=await receiptEffectsC(f.id),prior=(await admin.query('SELECT ($1::date-1)::text AS day',[f.plan.paymentDate])).rows[0].day;const variants=[{...f.plan,paymentDate:prior},{...f.plan,borrowerId:fixture.otherBorrowerId},{...f.plan,paymentMethod:'Cash'},{...f.plan,cashAccountId:fixture.receivingAccountId},{...f.plan,targetLoanId:f.loan.targetId},{...f.plan,amountReceived:'8',allocations:[{...f.plan.allocations[0],interest:'8'}]}];for(const plan of variants){const cmd=await correctionPlanCommandC(f.id,plan),r=await store.operation(principal,cmd);assert.equal(r.originalOutcome?.status,'rejected',JSON.stringify(r));assert.deepEqual(await receiptEffectsC(f.id),before);assert.deepEqual((await store.operation(principal,cmd)).originalOutcome,r.originalOutcome)}await app.query('UPDATE "Loans" SET "Auto Charge Enabled"=false WHERE "Row ID"=$1',[f.loan.targetId]);const disabled=await store.operation(principal,await correctionPlanCommandC(f.id,f.plan));assert.equal(disabled.originalOutcome?.status,'rejected',JSON.stringify(disabled));assert.deepEqual(await receiptEffectsC(f.id),before);const fixed=await firstdayTransitionC(loanTypesC[2]),wrongtype=await store.operation(principal,await correctionPlanCommandC(fixed.id,fixed.plan));assert.equal(wrongtype.originalOutcome?.status,'rejected',JSON.stringify(wrongtype));const p=(await store.paymentRecord(principal,f.id,{preview:true})).item,foreign=p.balances.find(row=>row.chargeId===fixture.chargeIds[1]);const multi={...f.plan,amountReceived:'10',allocations:[...f.plan.allocations,{chargeId:foreign.chargeId,principal:'0',interest:'1',expectedPrincipalRemaining:String(Number(foreign.principalRemaining)),expectedInterestRemaining:String(Number(foreign.interestRemaining)),chargeDate:foreign.chargeDate}]};assert.equal((await store.operation(principal,await correctionPlanCommandC(f.id,multi))).originalOutcome?.status,'rejected');assert.deepEqual(await receiptEffectsC(f.id),before)});
test('F8-C08 same-target historical Close date and Notes account edits reuse booked obligations without fresh preparation',async()=>{const f=await selectedCloseTransitionC(),close=await preparedCorrectionC(f),r=await store.operation(principal,close);assert.equal(r.originalOutcome?.status,'applied',JSON.stringify(r));const prior=(await admin.query('SELECT ($1::date-1)::text AS day',[f.day])).rows[0].day,historical=await correctionPlanCommandC(f.id,{...close.inputs.fields,paymentDate:prior}),h=await store.operation(principal,historical);assert.equal(h.originalOutcome?.status,'applied',JSON.stringify(h));const charges=await admin.query('SELECT to_jsonb(c) value FROM "Charges" c WHERE "Ref Loans"=$1 ORDER BY "Row ID"',[f.loan.targetId]);await app.query('UPDATE "Loans" SET "Auto Charge Enabled"=false WHERE "Row ID"=$1',[f.loan.targetId]);const metadata=await correctionPlanCommandC(f.id,{...historical.inputs.fields,notes:'historical metadata ไทย',cashAccountId:fixture.lendingAccountId}),m=await store.operation(principal,metadata);assert.equal(m.originalOutcome?.status,'applied',JSON.stringify(m));assert.deepEqual((await admin.query('SELECT to_jsonb(c) value FROM "Charges" c WHERE "Ref Loans"=$1 ORDER BY "Row ID"',[f.loan.targetId])).rows,charges.rows);const current=(await store.paymentRecord(principal,f.id)).item;assert.equal(current.paymentDate,prior);assert.equal(current.notes,'historical metadata ไทย');assert.equal(current.cashMovements.length,1);assert.equal((await store.loanRecord(principal,f.loan.targetId)).item.status,'ปิดยอดแล้ว');assert.deepEqual((await store.operation(principal,historical)).originalOutcome,h.originalOutcome);assert.deepEqual((await store.operation(principal,close)).originalOutcome,r.originalOutcome)});
test('F8-C09 Close retarget preview is readonly and excludes only own effects while preserving another receipt',async()=>{const f=await selectedCloseTransitionC(false),other={...f.original,requestId:randomUUID(),allocations:[{...f.original.allocations[0],principal:'0',interest:'1',expectedPrincipalRemaining:'20'}],amountReceived:'1'};const postedOther=await store.submit(principal,other);assert.equal(postedOther.originalOutcome?.status,'posted',JSON.stringify(postedOther));const otherId=postedOther.originalOutcome.paymentId,otherBefore=await receiptEffectsC(otherId),first=await preparedCorrectionC(f),r=await store.operation(principal,first);assert.equal(r.originalOutcome?.status,'applied',JSON.stringify(r));assert.deepEqual(await receiptEffectsC(otherId),otherBefore);const target=await closingLoanC(true),sourceBefore=await receiptEffectsC(f.id),targetBefore=await lifecycleEffectsC(target.c.targetId),cmd=await preparedCorrectionC(f,target.c.targetId);assert.deepEqual(await receiptEffectsC(f.id),sourceBefore);assert.deepEqual(await lifecycleEffectsC(target.c.targetId),targetBefore);const result=await store.operation(principal,cmd);assert.equal(result.originalOutcome?.status,'applied',JSON.stringify(result));assert.deepEqual(await receiptEffectsC(otherId),otherBefore);assert.equal((await store.loanRecord(principal,target.c.targetId)).item.status,'ปิดยอดแล้ว');assert.equal((await store.loanRecord(principal,f.loan.targetId)).item.status,'ยังไม่ปิดยอด');const final=await receiptEffectsC(f.id);await app.query('SELECT public.post_payment($1)',[f.id]);assert.deepEqual(await receiptEffectsC(f.id),final);assert.deepEqual((await store.operation(principal,cmd)).originalOutcome,result.originalOutcome)});
test('F8-C10 Close destination stale plan and foreign-owned manual default closure cannot manufacture eligibility',async()=>{const f=await selectedCloseTransitionC(),cmd=await preparedCorrectionC(f),today='C-TODAY-'+f.loan.targetId;await app.query('UPDATE "Charges" SET "Principal Due"="Principal Due"+1::money,"Interest Due"="Interest Due"-1::money WHERE "Row ID"=$1',[today]);const before=await receiptEffectsC(f.id),stale=await store.operation(principal,cmd);assert.equal(stale.originalOutcome?.code,'source_conflict',JSON.stringify(stale));assert.deepEqual(await receiptEffectsC(f.id),before);const current=(await store.paymentRecord(principal,f.id,{preview:true})).item;cmd.requestId=randomUUID();cmd.expectedVersion=current.sourceVersion;const changed=await store.operation(principal,cmd);assert.equal(changed.originalOutcome?.code,'plan_changed',JSON.stringify(changed));assert.deepEqual(await receiptEffectsC(f.id),before);assert.deepEqual((await store.operation(principal,cmd)).originalOutcome,changed.originalOutcome);for(const kind of ['other-receipt','manual','default']){const target=await closingLoanC(true),fresh=await preparedCorrectionC(f,target.c.targetId);if(kind==='other-receipt'){const p=await store.loanClosePreview(principal,target.c.targetId),r=await store.operation(principal,closeCommandC(target.c,p));assert.equal(r.originalOutcome?.status,'applied',JSON.stringify(r))}else if(kind==='default'){const source=(await store.loanRecord(principal,target.c.targetId)).item;assert.equal((await store.operation(principal,loanOperationC('loan.default',target.c.targetId,source.version,{businessDate:f.day}))).originalOutcome?.status,'applied')}else await app.query('UPDATE "Loans" SET "Loan Status"=\'ปิดยอดแล้ว\',"Close Date"=$2::date,"Closed By"=$3 WHERE "Row ID"=$1',[target.c.targetId,f.day,OWNER_EMAIL]);const targetBefore=await lifecycleEffectsC(target.c.targetId),original=await receiptEffectsC(f.id),denied=await store.operation(principal,fresh);assert.equal(denied.originalOutcome?.status,'rejected',JSON.stringify(denied));assert.deepEqual(await receiptEffectsC(f.id),original);assert.deepEqual(await lifecycleEffectsC(target.c.targetId),targetBefore);assert.deepEqual((await store.operation(principal,fresh)).originalOutcome,denied.originalOutcome)}});

test('F8-C11 entering Close preparation and repost faults rollback charges original receipt loan and staged revision',async()=>{for(const stage of ['prepare-new','prepare-update','repost']){const f=await selectedCloseTransitionC(stage!=='prepare-new'),cmd=await preparedCorrectionC(f),before={receipt:await receiptEffectsC(f.id),loan:await lifecycleEffectsC(f.loan.targetId),charges:(await admin.query('SELECT to_jsonb(c) value FROM "Charges" c WHERE "Ref Loans"=$1 ORDER BY "Row ID"',[f.loan.targetId])).rows};const table=stage==='repost'?'Repayments':'Charges',event=stage==='prepare-update'?'UPDATE':'INSERT',condition=stage==='repost'?`NEW."Ref Payment"='${f.id}'`:`NEW."Ref Loans"='${f.loan.targetId}'`;await admin.query(`CREATE FUNCTION public.c_destination_fault() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF ${condition} THEN RAISE EXCEPTION 'synthetic destination branch fault';END IF;RETURN NEW;END$$;CREATE TRIGGER zzz_c_destination_fault AFTER ${event} ON "${table}" FOR EACH ROW EXECUTE FUNCTION public.c_destination_fault()`);try{const r=await store.operation(principal,cmd);assert.equal(r.status,503,JSON.stringify(r));assert.equal(r.code,'operation_outcome_unknown');assert.deepEqual(await rows(cmd.requestId),[]);assert.equal((await store.operationStatus(principal,cmd.requestId)).kind,'unresolved');assert.deepEqual(await receiptEffectsC(f.id),before.receipt);assert.deepEqual(await lifecycleEffectsC(f.loan.targetId),before.loan);assert.deepEqual((await admin.query('SELECT to_jsonb(c) value FROM "Charges" c WHERE "Ref Loans"=$1 ORDER BY "Row ID"',[f.loan.targetId])).rows,before.charges)}finally{await admin.query(`DROP TRIGGER zzz_c_destination_fault ON "${table}";DROP FUNCTION public.c_destination_fault()`)}const recovered=await store.operation(principal,cmd);assert.equal(recovered.originalOutcome?.status,'applied',JSON.stringify(recovered));assert.equal((await rows(cmd.requestId)).length,1)}});

