test('F11-C03 operational Dashboard exact KPI provider rounding and independent pending profit signed expense unfiltered statuses',async()=>{
 await admin.query('INSERT INTO "Statistics"("Row ID","Statistics ID") VALUES($1,$2)',[randomUUID(),'C dashboard']);const dates=(await app.query("SELECT (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Bangkok')::date::text AS day,((CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Bangkok')::date-1)::text AS yesterday,(date_trunc('month',CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Bangkok')+interval '1 month - 1 day')::date::text AS monthend,date_trunc('month',CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Bangkok')::date::text AS monthstart,(date_trunc('month',CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Bangkok')-interval '1 day')::date::text AS priormonth")).rows[0],ids={};
 for(const status of ['Not Paid','Partially Paid','Fully Paid','Overdue']){const borrower=randomUUID();await app.query('INSERT INTO "Borrowers"("Row ID","Borrower Name","Hidden Flag") VALUES($1,$2,$3)',[borrower,'C Dashboard '+status,status==='Fully Paid']);const loan=await operationalLoanC(borrower,-3),charge=await operationalChargeC(loan,status==='Overdue'?dates.yesterday:dates.day,'10','2');ids[status]=borrower;if(status==='Fully Paid')await operationalSourcePaymentC(borrower,charge,dates.day,'12');else if(status==='Partially Paid'){const c={schemaVersion:6,requestId:randomUUID(),borrowerId:borrower,amountReceived:'6',paymentDate:dates.day,paymentMethod:'Cash',cashAccountId:fixture.receivingAccountId,notes:null,receiptId:null,allocations:[{chargeId:charge,principal:'5',interest:'1',expectedPrincipalRemaining:'10',expectedInterestRemaining:'2',chargeDate:dates.day}]};assert.equal((await store.submit(principal,c)).originalOutcome?.status,'posted')}}
 for(const [date,interest] of [[dates.yesterday,'3'],[dates.monthstart,'7'],[dates.priormonth,'11']]){const loan=await operationalLoanC(fixture.borrowerId,-60),charge=await operationalChargeC(loan,date,'0',interest);await operationalSourcePaymentC(fixture.borrowerId,charge,date,interest)}await expenseCreateC({...await expenseFieldsC(),amount:'-3',paidByAccountId:null,notes:'signed expense correction'});
 const result=await store.dashboard(principal);assert.equal(result.status,200,JSON.stringify(result));const projection=Object.entries(dashboardMetricsC).map(([k,v])=>'"'+v+'"::text AS "'+k+'"').join(','),source=(await app.query('SELECT DISTINCT '+projection+' FROM olap_portfolio_summary')).rows;assert.equal(source.length,1);const row=source[0],flat={...result,...result.collection,...result.forecast,...result.portfolio};for(const [key,value] of Object.entries(row))assert.equal(String(flat[key]),value,key);assert.equal(result.businessDate,dates.day);assert.match(result.asOf,/Z$/);assert.equal('outstandingPrincipal' in result.portfolio,false);assert.equal('totalOutstandingPrincipal' in result,false);assert.deepEqual(Object.keys(result.collection).sort(),['fullyPaid','notPaid','overdue','partiallyPaid']);
 const formulas=(await app.query(`SELECT round(coalesce((SELECT sum(c."Principal Due"::numeric+c."Interest Due"::numeric-coalesce(p.p,0)-coalesce(p.i,0)) FROM "Charges" c LEFT JOIN LATERAL(SELECT sum(r."Principal Paid"::numeric) p,sum(r."Interest Paid"::numeric) i FROM "Repayments" r WHERE r."Ref Charges"=c."Row ID") p ON true WHERE c."Ref Loans" IS NOT NULL AND c."Charge Date"<=$1::date),0),0)::text pending,round(coalesce((SELECT sum("Interest Paid"::numeric) FROM "Repayments" WHERE "Payment Date"=$1::date),0),0)::text today,round(coalesce((SELECT sum("Interest Paid"::numeric) FROM "Repayments" WHERE "Payment Date"=$1::date-1),0),0)::text yesterday,round(coalesce((SELECT sum("Interest Paid"::numeric) FROM "Repayments"),0)-coalesce((SELECT sum("Amount"::numeric) FROM "Business Expenses"),0),0)::text net,round(coalesce((SELECT sum("Interest Paid"::numeric) FROM "Repayments" WHERE "Payment Date" BETWEEN date_trunc('month',$1::date)::date AND (date_trunc('month',$1::date)+interval '1 month - 1 day')::date),0),0)::text mtd`,[dates.day])).rows[0];assert.deepEqual([result.pendingPaymentAmount,result.todayProfit,result.yesterdayProfit,result.netProfit,result.forecast.realizedProfitMtd],[formulas.pending,formulas.today,formulas.yesterday,formulas.net,formulas.mtd]);for(const [status,id] of Object.entries(ids))assert.equal((await app.query('SELECT "Daily Collection Status" status FROM olap_borrowers_analytics WHERE "Row ID"=$1',[id])).rows[0].status,status);const counts=(await app.query('SELECT "Daily Collection Status" status,count(*)::int n FROM olap_borrowers_analytics GROUP BY 1')).rows;for(const [key,status] of Object.entries({fullyPaid:'Fully Paid',notPaid:'Not Paid',overdue:'Overdue',partiallyPaid:'Partially Paid'}))assert.equal(result.collection[key],counts.find(r=>r.status===status)?.n??0);const cash=await store.cashOverview(principal);assert.deepEqual(result.incomeMtd,cash.dashboard);assert.deepEqual(result.businessCashHeld,cash.accounts);
});
test('F11-C04 operational Dashboard unavailable provider never fabricates zero; duplicate Statistics collapse and unauthorized actor denied',async()=>{
 const stats=(await admin.query('SELECT "Row ID" id FROM "Statistics"')).rows;await admin.query('DELETE FROM "Statistics"');assert.equal((await store.dashboard(principal)).status,503);await admin.query('INSERT INTO "Statistics"("Row ID","Statistics ID") VALUES($1,\'C same\'),($2,\'C same\')',[randomUUID(),randomUUID()]);const r=await store.dashboard(principal);assert.equal(r.status,200,JSON.stringify(r));let businessQueries=0;const unauthorized={async connect(){throw Error('Unauthorized business connection')}};const forbidden=createApplicationRoleCommandStore({pool:unauthorized,targetAttestation:proof,ownerTesting:true});assert.equal((await forbidden.dashboard({...principal,email:'other@example.invalid'})).status,403);
 for(const mode of ['null','conflicting']){const pool={async connect(){const c=await app.connect();return{async query(sql,...params){if(sql.startsWith('SELECT DISTINCT')&&sql.includes('olap_portfolio_summary')){businessQueries++;const real=await c.query(sql,...params);return{...real,rows:mode==='null'?[{...real.rows[0],todayProfit:null}]:[real.rows[0],{...real.rows[0],todayProfit:'999'}]}}return c.query(sql,...params)},release:q=>c.release(q)}}};const bad=createApplicationRoleCommandStore({pool,targetAttestation:proof,ownerTesting:true}),result=await bad.dashboard(principal);assert.equal(result.status,503);assert.equal('pendingPaymentAmount' in result,false)}assert.equal(businessQueries,2);
});
test('F11-C05 standalone Upcoming seven-day window hidden future-only and tie pages retain complete source membership date totals and rollover guards',async()=>{
 const borrower=randomUUID(),outside=randomUUID();await app.query('INSERT INTO "Borrowers"("Row ID","Borrower Name","Hidden Flag") VALUES($1,\'C hidden future-only\',true),($2,\'C first-five day8\',false)',[borrower,outside]);const days=(await app.query("SELECT i,((CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Bangkok')::date+i)::text AS day FROM generate_series(1,8)i ORDER BY i")).rows;const loan=await operationalLoanC(borrower);for(const row of days.slice(0,7))await operationalChargeC(loan,row.day);const outsideLoan=await operationalLoanC(outside);await operationalChargeC(outsideLoan,days[7].day);for(let i=0;i<26;i++)await operationalChargeC(await operationalLoanC(borrower),days[0].day);assert.equal((await app.query('SELECT count(*)::int n FROM "Charges" c JOIN "Loans" l ON l."Row ID"=c."Ref Loans" WHERE l."Ref Borrowers"=$1 AND ((c."Payment Status"<>\'ชำระแล้ว\' AND c."Charge Date"<=(CURRENT_TIMESTAMP AT TIME ZONE \'Asia/Bangkok\')::date) OR (c."Payment Status"=\'ชำระแล้ว\' AND c."Payment Date"=(CURRENT_TIMESTAMP AT TIME ZONE \'Asia/Bangkok\')::date) OR EXISTS(SELECT 1 FROM "Repayments" r WHERE r."Ref Charges"=c."Row ID" AND r."Payment Date"=(CURRENT_TIMESTAMP AT TIME ZONE \'Asia/Bangkok\')::date))',[borrower])).rows[0].n,0);
 const first=await store.upcoming(principal,{limit:2});assert.equal(first.status,200,JSON.stringify(first));const source=(await app.query(`SELECT s."Row ID" id,s."Ref Borrower" AS "borrowerId",s."Due Date"::text AS "dueDate",s."Total Charge"::text AS "totalCharge",concat_ws(' - ',nullif(b."Borrower Name",''),nullif(b."Description",'')) AS label FROM oltp_upcoming_charge_summary_v2 s JOIN "Borrowers" b ON b."Row ID"=s."Ref Borrower" WHERE s."As Of Date"=$1::date AND s."Due Date" BETWEEN $2::date AND $3::date ORDER BY s."Due Date",concat_ws(\' - \',nullif(b."Borrower Name",\'\'),nullif(b."Description",\'\')) COLLATE "C",s."Ref Borrower" COLLATE "C"`,[first.businessDate,first.fromDate,first.throughDate])).rows;let items=[],page=first;do{assert.equal(page.businessDate,first.businessDate);assert.deepEqual(page.dateTotals,first.dateTotals);items.push(...page.items);assert.ok(items.length<=source.length);if(!page.nextCursor)break;page=await store.upcoming(principal,{limit:2,cursor:page.nextCursor});assert.equal(page.status,200)}while(true);assert.deepEqual(items,source);assert.equal(items.filter(r=>r.borrowerId===borrower).length,7);assert.equal(items.filter(r=>r.borrowerId===outside).length,0);assert.equal((await app.query('SELECT count(*)::int n FROM oltp_upcoming_charge_summary_v2 WHERE "Ref Borrower"=$1',[outside])).rows[0].n,1);
 const authoritative=(await app.query('SELECT "Total Charge"::text amount FROM oltp_upcoming_charge_summary_v2 WHERE "Ref Borrower"=$1 AND "Due Date"=$2',[borrower,days[0].day])).rows[0].amount;let cursor=null,detail=[],detailCursor=null;do{const p=await store.upcoming(principal,{borrowerId:borrower,dueDate:days[0].day,businessDate:first.businessDate,limit:5,cursor});assert.equal(p.status,200,JSON.stringify(p));assert.equal(p.totalCharge,authoritative);assert.equal(p.forecastNote,first.forecastNote);detail.push(...p.items);cursor=p.nextCursor;detailCursor??=cursor;assert.ok(detail.length<=27)}while(cursor);const eventIds=(await app.query('SELECT "Row ID" id FROM oltp_upcoming_charge_events_v1 WHERE "Ref Borrower"=$1 AND "Due Date"=$2 AND "As Of Date"=$3 ORDER BY "Row ID" COLLATE "C"',[borrower,days[0].day,first.businessDate])).rows.map(r=>r.id);assert.deepEqual(detail.map(r=>r.id),eventIds);assert.equal(detail.length,27);assert.ok(detail.every(r=>r.basis==='Recorded settlement'));
 const wrong=await store.upcoming(principal,{borrowerId:borrower,dueDate:days[1].day,businessDate:first.businessDate,limit:5,cursor:detailCursor});assert.equal(wrong.status,400);const prior=(await app.query('SELECT ($1::date-1)::text AS day',[first.businessDate])).rows[0].day,decoded=JSON.parse(Buffer.from(first.nextCursor,'base64url').toString());decoded.day=prior;assert.equal((await store.upcoming(principal,{limit:2,cursor:Buffer.from(JSON.stringify(decoded)).toString('base64url')})).status,409);assert.equal((await store.upcoming(principal,{borrowerId:borrower,dueDate:days[0].day,businessDate:prior})).status,409);assert.equal((await store.upcoming(principal,{borrowerId:outside,dueDate:days[7].day,businessDate:first.businessDate})).status,400);assert.match(first.forecastNote,/Auto-off loans use recorded settlement charges only/);
});
test('F8-C12 scoped PWA borrower reassignment preserves other receipt and rejects mixed plans with immutable replay',async()=>{
 const f=await revisionFixtureC(),original=await rows(f.command.requestId),loan=await loanCommandC(loanTypesC[2],false);loan.inputs.borrowerId=fixture.otherBorrowerId;assert.equal((await store.operation(principal,loan)).status,200);const charge=randomUUID();await app.query('INSERT INTO "Charges"("Row ID","Ref Loans","Charge Date","Principal Due","Interest Due") VALUES($1,$2,$3,40::money,100::money)',[charge,loan.targetId,loan.inputs.loanDate]);
 const other={schemaVersion:6,requestId:randomUUID(),borrowerId:fixture.otherBorrowerId,allocations:[{chargeId:charge,principal:'5',interest:'0',expectedPrincipalRemaining:'40',expectedInterestRemaining:'100',chargeDate:loan.inputs.loanDate}],cashAccountId:fixture.receivingAccountId,paymentDate:loan.inputs.loanDate,amountReceived:'5',paymentMethod:'Cash',notes:'other receipt preserve',receiptId:null},paid=await store.submit(principal,other);assert.equal(paid.originalOutcome.status,'posted');const otherBefore=await receiptEffectsC(paid.originalOutcome.paymentId);
 const p=(await store.paymentRecord(principal,f.id,{preview:true,proposedBorrowerId:fixture.otherBorrowerId})).item;assert.equal(p.proposedBorrowerId,fixture.otherBorrowerId);assert.equal(p.source.borrowerId,fixture.borrowerId);assert.ok(p.balances.every(r=>r.loanId===loan.targetId||r.loanId===fixture.loanIds[2]));const balance=p.balances.find(r=>r.chargeId===charge);assert.equal(Number(balance.principalRemaining),35);
 const fields={borrowerId:fixture.otherBorrowerId,amountReceived:'50',paymentDate:f.command.paymentDate,paymentMethod:'Cash',cashAccountId:fixture.receivingAccountId,notes:'reassigned exact ไทย',allocationMethod:'Selected Charges',targetChargeId:null,targetLoanId:null,allocations:[{chargeId:charge,principal:'30',interest:'20',expectedPrincipalRemaining:'35',expectedInterestRemaining:'100',chargeDate:loan.inputs.loanDate}]};
 const cmd={requestId:randomUUID(),operation:'payment.correct',targetId:f.id,expectedVersion:p.sourceVersion,predecessorRequestId:p.predecessorRequestId,receiptId:null,inputs:{kind:'pwa-plan',receiptMode:'preserve',fields}},r=await store.operation(principal,cmd);assert.equal(r.originalOutcome?.status,'applied',JSON.stringify(r));const current=(await store.paymentRecord(principal,f.id)).item;assert.equal(current.borrowerId,fixture.otherBorrowerId);assert.equal(current.originalOutcomeStatus,'posted');assert.equal(current.status,'Posted');assert.equal(current.allocations[0].chargeId,charge);assert.deepEqual(await receiptEffectsC(paid.originalOutcome.paymentId),otherBefore);assert.deepEqual(await rows(f.command.requestId),original);assert.deepEqual((await store.submit(principal,f.command)).originalOutcome,f.posted.originalOutcome);assert.deepEqual((await store.operation(principal,cmd)).originalOutcome,r.originalOutcome);
 const before=await receiptEffectsC(f.id),fresh=(await store.paymentRecord(principal,f.id,{preview:true})).item,mixed={...cmd,requestId:randomUUID(),expectedVersion:fresh.sourceVersion,predecessorRequestId:fresh.predecessorRequestId,inputs:{...cmd.inputs,fields:{...fields,allocations:[{...fields.allocations[0],principal:'20',interest:'0'},{chargeId:f.ids[0],principal:'0',interest:'30',expectedPrincipalRemaining:'40',expectedInterestRemaining:'100',chargeDate:f.command.paymentDate}]}}};assert.equal((await store.operation(principal,mixed)).originalOutcome?.status,'rejected');assert.deepEqual(await receiptEffectsC(f.id),before);assert.deepEqual(await receiptEffectsC(paid.originalOutcome.paymentId),otherBefore);
});
test('F8-C13 old schema3 through5 legacy receipt corrections retain engine root bytes and reassign borrower',async()=>{
 for(const schemaVersion of [3,4,5]){const loan=await loanCommandC(loanTypesC[2],false),dest=await loanCommandC(loanTypesC[2],false);dest.inputs.borrowerId=fixture.otherBorrowerId;assert.equal((await store.operation(principal,loan)).status,200);assert.equal((await store.operation(principal,dest)).status,200);const ids=[randomUUID(),randomUUID()];for(const [i,l] of [loan,dest].entries())await app.query('INSERT INTO "Charges"("Row ID","Ref Loans","Charge Date","Principal Due","Interest Due") VALUES($1,$2,$3,100::money,20::money)',[ids[i],l.targetId,l.inputs.loanDate]);
 const root={schemaVersion,requestId:randomUUID(),borrowerId:fixture.borrowerId,selectedChargeIds:[ids[0]],cashAccountId:fixture.receivingAccountId,paymentDate:loan.inputs.loanDate,amountReceived:'120',paymentMethod:'Bank Transfer',allocationMethod:'Selected Charges',notes:'legacy original '+schemaVersion,receiptId:null},posted=await store.submit(principal,root);assert.equal(posted.originalOutcome?.status,'posted',JSON.stringify(posted));const id=posted.originalOutcome.paymentId,original=await rows(root.requestId),p=(await store.paymentRecord(principal,id,{preview:true,proposedBorrowerId:fixture.otherBorrowerId})).item;assert.equal(p.origin,'legacy-source');assert.equal(p.predecessorRequestId,root.requestId);
 const cmd={requestId:randomUUID(),operation:'payment.correct',targetId:id,expectedVersion:p.sourceVersion,predecessorRequestId:p.predecessorRequestId,receiptId:null,inputs:{kind:'legacy-source',receiptMode:'preserve',fields:{borrowerId:fixture.otherBorrowerId,amountReceived:'120',paymentDate:root.paymentDate,paymentMethod:'Bank Transfer',cashAccountId:fixture.receivingAccountId,notes:'legacy updated ไทย',allocationMethod:'Selected Charges',targetChargeId:null,targetLoanId:null,selectedChargeIds:[ids[1]]}}},r=await store.operation(principal,cmd);assert.equal(r.originalOutcome?.status,'applied',JSON.stringify(r));const after=(await store.paymentRecord(principal,id)).item;assert.equal(after.borrowerId,fixture.otherBorrowerId);assert.equal(after.allocations[0].chargeId,ids[1]);assert.equal(Number(after.allocations[0].principal),100);assert.equal(Number(after.allocations[0].interest),20);assert.equal((await store.paymentRecord(principal,id,{preview:true})).item.origin,'legacy-source');assert.deepEqual(await rows(root.requestId),original);assert.deepEqual((await store.submit(principal,root)).originalOutcome,posted.originalOutcome);assert.deepEqual((await store.operation(principal,cmd)).originalOutcome,r.originalOutcome);const snapshot=await receiptEffectsC(id);await app.query('SELECT public.post_payment($1)',[id]);assert.deepEqual(await receiptEffectsC(id),snapshot);}
});
test('F8-C14 leaving governed Close reverses referral and own closure with exact source history and stable replay',async()=>{
 const ref=await create(),old=(await admin.query('SELECT "Ref Referrer" id FROM "Borrowers" WHERE "Row ID"=$1',[fixture.borrowerId])).rows[0].id;try{await app.query('UPDATE "Borrowers" SET "Ref Referrer"=$2 WHERE "Row ID"=$1',[fixture.borrowerId,ref.c.targetId]);const f=await selectedCloseTransitionC(),close=await preparedCorrectionC(f),r=await store.operation(principal,close);assert.equal(r.originalOutcome?.status,'applied',JSON.stringify(r));assert.equal((await store.loanRecord(principal,f.loan.targetId)).item.status,'ปิดยอดแล้ว');const referral=(await admin.query('SELECT to_jsonb(e) value FROM "Business Expenses" e WHERE "Row ID"=$1',['rr1:'+f.loan.targetId])).rows;assert.equal(referral.length,1);const p=(await store.paymentRecord(principal,f.id,{preview:true})).item,row=p.balances.find(r=>r.chargeId===f.original.allocations[0].chargeId);assert.ok(row);const plan={borrowerId:fixture.borrowerId,amountReceived:'10',paymentDate:f.day,paymentMethod:'Cash',cashAccountId:fixture.receivingAccountId,notes:'leave Close exact',allocationMethod:'Selected Charges',targetChargeId:null,targetLoanId:null,allocations:[{chargeId:row.chargeId,principal:'10',interest:'0',expectedPrincipalRemaining:String(Number(row.principalRemaining)),expectedInterestRemaining:String(Number(row.interestRemaining)),chargeDate:row.chargeDate}]},cmd=await correctionPlanCommandC(f.id,plan),left=await store.operation(principal,cmd);assert.equal(left.originalOutcome?.status,'applied',JSON.stringify(left));assert.notEqual((await store.loanRecord(principal,f.loan.targetId)).item.status,'ปิดยอดแล้ว');assert.deepEqual((await admin.query('SELECT to_jsonb(e) value FROM "Business Expenses" e WHERE "Row ID"=$1',['rr1:'+f.loan.targetId])).rows,[]);const snapshot=await receiptEffectsC(f.id);assert.equal(snapshot.allocations.length,1);assert.equal((await store.paymentRecord(principal,f.id)).item.notes,'leave Close exact');assert.deepEqual((await store.operation(principal,close)).originalOutcome,r.originalOutcome);assert.deepEqual((await store.operation(principal,cmd)).originalOutcome,left.originalOutcome);assert.deepEqual(await receiptEffectsC(f.id),snapshot)}finally{await app.query('UPDATE "Borrowers" SET "Ref Referrer"=$2 WHERE "Row ID"=$1',[fixture.borrowerId,old])}
});

test('F12-C01 actual owner receipt reads follow current source priority and Collection membership across dates with one multi-charge card',async()=>{
 const f=await revisionFixtureC(),day=f.command.paymentDate,p=(await store.draft(principal,fixture.borrowerId,{scope:'all',selectedChargeIds:f.ids,limit:100})),chargeRows=f.ids.map(id=>p.charges.find(r=>r.id===id)),multi={schemaVersion:6,requestId:randomUUID(),borrowerId:fixture.borrowerId,allocations:chargeRows.map(r=>({chargeId:r.id,principal:'0',interest:'10',expectedPrincipalRemaining:r.principalRemaining,expectedInterestRemaining:r.interestRemaining,chargeDate:r.chargeDate})),cashAccountId:fixture.receivingAccountId,paymentDate:day,amountReceived:'20',paymentMethod:'Cash',notes:'multi related receipt',receiptId:null},posted=await store.submit(principal,multi);assert.equal(posted.originalOutcome.status,'posted');
 const page=await store.collectionReceipts(principal,fixture.borrowerId,{businessDate:day,chargeIds:f.ids,limit:1});assert.equal(page.status,200,JSON.stringify(page));assert.equal(page.items.length,1);assert.ok(page.nextCursor);const second=await store.collectionReceipts(principal,fixture.borrowerId,{businessDate:day,chargeIds:[...f.ids].reverse(),limit:1,cursor:page.nextCursor});assert.equal(second.status,200);assert.equal(second.nextCursor,null);assert.deepEqual(new Set([...page.items,...second.items].map(x=>x.id)),new Set([f.id,posted.originalOutcome.paymentId]));assert.equal((await store.collectionReceipts(principal,fixture.borrowerId,{businessDate:day,chargeIds:[f.ids[0]],limit:1,cursor:page.nextCursor})).status,400);assert.equal((await store.collectionReceipts(principal,fixture.borrowerId,{businessDate:day,chargeIds:[fixture.chargeIds[3]],limit:25})).status,409);
 await app.query('UPDATE "Payments" SET "Uploaded Receipt"=$2 WHERE "Row ID"=$1',[f.id,'manual-receipts/dev/unknown-synthetic-native.png']);let reads=[];const images=createApplicationRoleCommandStore({pool:app,targetAttestation:proof,ownerTesting:true,sourceReceiptReader:async(reference,kind)=>{reads.push({reference,kind});throw Error('receipt_reference_unsupported')}});
 assert.equal((await images.paymentImage({...principal,email:'foreign@example.invalid'},f.id)).status,403);assert.deepEqual(reads,[]);assert.equal((await images.paymentImage(principal,randomUUID())).status,404);assert.deepEqual(reads,[]);assert.equal((await images.paymentImage(principal,f.id,'preferred')).status,422);assert.deepEqual(reads,[{reference:'manual-receipts/dev/unknown-synthetic-native.png',kind:'manual'}]);assert.equal((await images.paymentImage(principal,f.id,'agent')).status,404);assert.equal(reads.length,1);assert.equal((await images.paymentImage(principal,f.id,'url')).status,400);assert.equal(reads.length,1);
 const current=(await store.paymentRecord(principal,f.id)).item;assert.equal(current.receiptReference,'manual-receipts/dev/unknown-synthetic-native.png');assert.equal(current.originalOutcomeStatus,'posted');assert.equal(current.status,'Posted');assert.deepEqual((await store.submit(principal,f.command)).originalOutcome,f.posted.originalOutcome);
 const charge=await store.chargeRecord(principal,f.ids[0]);assert.equal(charge.status,200);assert.ok(charge.item.allocations.some(a=>a.paymentId===f.id));assert.ok(charge.item.repayments.some(r=>r.paymentId===f.id));
});
test('F11-C06 initialized cash statement carries pre-window opening and exact signed running provider balances',async()=>{
 const options=await store.expenseOptions(principal),day=options.businessDate,prior=(await admin.query('SELECT ($1::date-16)::text AS day',[day])).rows[0].day;
 await expenseCreateC({...await expenseFieldsC(),expenseDate:prior,amount:'11',notes:'pre-window expense'});
 const balance=(await admin.query('SELECT "Current Balance"::text value FROM "Cash Holder Balances" WHERE "Ref Cash Holder"=$1',['ch:dad'])).rows[0].value;
 const accounts=(await admin.query('SELECT a."Row ID" id FROM "Cash Accounts" a LEFT JOIN r008_cash_account_cutover c ON c."Ref Cash Account"=a."Row ID" WHERE a."Ref Cash Holder"=$1 AND c."Ref Cash Account" IS NULL ORDER BY a."Row ID"',['ch:dad'])).rows;assert.ok(accounts.length);const openings=Object.fromEntries(accounts.map(a=>[a.id,a.id===fixture.receivingAccountId?balance:'0']));
 await admin.query('SELECT public.initialize_cash_accounts($1,$2::jsonb,$3,$4)',['ch:dad',JSON.stringify(openings),OWNER_EMAIL,'C governed synthetic initialization']);
 await expenseCreateC({...await expenseFieldsC(),expenseDate:day,amount:'7',notes:'current expense after opening'});
 const page=await store.cashStatement(principal,{accountId:fixture.receivingAccountId,date:day,limit:100});assert.equal(page.status,200,JSON.stringify(page));assert.equal(page.summary.initialized,true);assert.ok(page.summary.openingBalance!==null);assert.ok(page.items.some(r=>/^-7(?:\.0+)?$/.test(r.amount)));assert.ok(page.items.every(r=>r.balanceAfter!==null&&r.initialized===true));
 const expected=(await admin.query('SELECT "Row ID" id,"Signed Amount"::text amount,"Balance After"::text balance FROM "Cash Account Statement Recent" WHERE "Ref Cash Account"=$1 AND "Statement Date"=$2::date ORDER BY "Statement Date","Sort Timestamp",("Row ID"::jsonb->>0) COLLATE "C",("Row ID"::jsonb->>1) COLLATE "C"',[fixture.receivingAccountId,day])).rows;assert.deepEqual(page.items.map(r=>({id:r.id,amount:r.amount,balance:r.balanceAfter})),expected);const raw=(await admin.query('SELECT "Opening Balance"::text opening,"Closing Balance"::text closing,"Money Out"::text outgoing FROM "Cash Account Daily Summary Recent" WHERE "Ref Cash Account"=$1 AND "Statement Date"=$2::date',[fixture.receivingAccountId,day])).rows[0];assert.equal(page.summary.openingBalance,raw.opening);assert.equal(page.summary.closingBalance,raw.closing);assert.equal(page.summary.moneyOut,raw.outgoing);assert.notEqual(raw.opening,'0');assert.equal((await store.cashStatement(principal,{accountId:fixture.receivingAccountId,date:prior,limit:25})).status,400);
});
